import NativeMap from '../specs/OneNativeMapNativeComponent'
export function Map({
  onRegionChange,
  latitude = 37.7749,
  longitude = -122.4194,
  distance = 5000,
  markers,
  swiftStyle,
  style,
  ...props
}: Types.MapProps) {
  if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90)
    throw new Error('Map latitude must be between -90 and 90')
  if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180)
    throw new Error('Map longitude must be between -180 and 180')
  if (!Number.isFinite(distance) || distance <= 0)
    throw new Error('Map distance must be a positive number of metres')
  if (
    !Array.isArray(markers) ||
    markers.some(
      (marker) =>
        typeof marker?.id !== 'string' ||
        typeof marker?.label !== 'string' ||
        !Number.isFinite(marker?.latitude) ||
        !Number.isFinite(marker?.longitude)
    )
  )
    throw new Error(
      'Map markers must contain string id and label fields and finite latitude and longitude'
    )
  if (new Set(markers.map((marker) => marker.id)).size !== markers.length)
    throw new Error('Map marker ids must be unique')

  return (
    <NativeMap
      {...props}
      style={style}
      swiftStyle={swiftStyleNative(swiftStyle)}
      onNativeSDKEvent={({ nativeEvent }) =>
        dispatchSDKEvent(swiftStyle, nativeEvent.name, nativeEvent.value)
      }
      latitude={latitude}
      longitude={longitude}
      distance={distance}
      markers={markers}
      onNativeMapRegionChange={({ nativeEvent }) =>
        onRegionChange?.(
          nativeEvent.latitude,
          nativeEvent.longitude,
          nativeEvent.distance
        )
      }
    />
  )
}
import NativeTextField from '../specs/OneNativeTextFieldNativeComponent'
export function TextField({
  text,
  onTextChange,
  revision = 0,
  focused,
  onFocusChange,
  focusRevision = 0,
  onSubmit,
  label = '',
  disabled = false,
  prompt = '',
  textFieldStyle = 'automatic',
  submitLabel = '',
  textInputAutocapitalization = '',
  autocorrectionDisabled = false,
  keyboardType = '',
  textContentType = '',
  axis = 'horizontal',
  swiftStyle,
  style,
  ...props
}: Types.TextFieldProps) {
  if (typeof text !== 'string' && !isSyncState(text))
    throw new Error('TextField text must be a string or NativeState handle')
  assertSwiftUIValue(
    'TextFieldStyle',
    textFieldStyle,
    Number.parseFloat(String(Platform.Version))
  )
  if (submitLabel)
    assertSwiftUIValue(
      'SubmitLabel',
      submitLabel,
      Number.parseFloat(String(Platform.Version))
    )
  if (textInputAutocapitalization)
    assertSwiftUIValue(
      'TextInputAutocapitalization',
      textInputAutocapitalization,
      Number.parseFloat(String(Platform.Version))
    )
  assertSwiftUIValue('Axis', axis, Number.parseFloat(String(Platform.Version)))
  const syncHandle = syncHandleOf<string>(text)
  const syncedText = useSyncValue<string>(text)
  const controlled = useControlled<{
    value: string
    eventCount: number
    revision: number
  }>((event) => {
    syncHandle?.set(event.value)
    onTextChange(event.value)
  }, revision)
  const controlledFocus = useControlled<{
    value: boolean
    eventCount: number
    revision: number
  }>((event) => onFocusChange?.(event.value), focusRevision)
  return (
    <NativeTextField
      {...props}
      style={style}
      swiftStyle={swiftStyleNative(swiftStyle)}
      onNativeSDKEvent={({ nativeEvent }) =>
        dispatchSDKEvent(swiftStyle, nativeEvent.name, nativeEvent.value)
      }
      value={syncedText}
      acknowledgedEvent={controlled.acknowledgedEvent}
      revision={revision}
      syncStateId={syncHandle ? (getSyncStateId(syncHandle) ?? 0) : 0}
      focused={focused ?? false}
      acknowledgedFocusEvent={
        focused !== undefined ? controlledFocus.acknowledgedEvent : 0
      }
      focusRevision={focusRevision}
      label={label}
      disabled={disabled}
      prompt={prompt}
      textFieldStyle={textFieldStyle}
      submitLabel={submitLabel}
      textInputAutocapitalization={textInputAutocapitalization}
      autocorrectionDisabled={autocorrectionDisabled}
      keyboardType={keyboardType}
      textContentType={textContentType}
      axis={axis}
      onNativeTextFieldValueChange={({ nativeEvent }) =>
        controlled.onNativeChange(nativeEvent)
      }
      onNativeTextFieldFocusChange={({ nativeEvent }) =>
        controlledFocus.onNativeChange(nativeEvent)
      }
      onNativeTextFieldSubmit={({ nativeEvent }) => onSubmit?.()}
    />
  )
}
