import NativeAlert from '../specs/OneNativeAlertNativeComponent'
export function Alert({
  isPresented,
  onIsPresentedChange,
  revision = 0,
  onAction,
  title = '',
  message = '',
  presenting = undefined,
  actions,
  swiftStyle,
  style,
  ...props
}: Types.AlertProps) {
  for (const action of actions) {
    if (typeof action?.id !== 'string' || typeof action?.label !== 'string')
      throw new Error('Alert actions must contain string id and label fields')
    if (action.role)
      assertSwiftUIValue(
        'ButtonRole',
        action.role,
        Number.parseFloat(String(Platform.Version))
      )
  }
  if (new Set(actions.map((action) => action.id)).size !== actions.length)
    throw new Error('Alert action ids must be unique')
  if (presenting !== undefined && typeof presenting !== 'string')
    throw new Error('Alert presenting must be a string')
  if (!actions.length) throw new Error('Alert must have at least one action')

  const controlled = useControlled<{
    value: boolean
    eventCount: number
    revision: number
  }>((event) => onIsPresentedChange(event.value), revision)
  return (
    <NativeAlert
      {...props}
      style={[{ position: 'absolute', width: 0, height: 0 }, style]}
      swiftStyle={swiftStyleNative(swiftStyle)}
      onNativeSDKEvent={({ nativeEvent }) =>
        dispatchSDKEvent(swiftStyle, nativeEvent.name, nativeEvent.value)
      }
      value={isPresented}
      acknowledgedEvent={controlled.acknowledgedEvent}
      revision={revision}
      title={title}
      message={message}
      presenting={presenting ?? ''}
      hasPresenting={presenting !== undefined}
      actions={actions}
      onNativeAlertValueChange={({ nativeEvent }) =>
        controlled.onNativeChange(nativeEvent)
      }
      onNativeAlertAction={({ nativeEvent }) =>
        onAction?.(nativeEvent.id, nativeEvent.presenting)
      }
    />
  )
}
